function hashBucket(key) {
  // deterministic FNV-1a style hash, no Math.random
  let h = 2166136261 >>> 0;
  for (let i = 0; i < key.length; i++) {
    h ^= key.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h % 100;
}

function evaluate(flag, user) {
  for (const rule of flag.rules) {
    if (rule.kind === 'attribute') {
      if (user[rule.attr] === rule.value) return rule.variant;
    } else if (rule.kind === 'percentage') {
      const bucket = hashBucket(flag.key + ':' + user.id);
      if (bucket < rule.rollout) return 'on';
      return 'off';
    }
  }
  return flag.fallback;
}

const flag = {
  key: 'new-checkout',
  fallback: 'off',
  rules: [
    { kind: 'attribute', attr: 'plan', value: 'enterprise', variant: 'on' },
    { kind: 'percentage', rollout: 50 }
  ]
};

const users = [
  { id: 'alice', plan: 'free' },
  { id: 'bob', plan: 'enterprise' },
  { id: 'carol', plan: 'free' },
  { id: 'dana', plan: 'pro' }
];

for (const u of users) {
  console.log(u.id + ' -> ' + evaluate(flag, u));
}

