// called on the request hot path for every flag decision
async function isEnabled(flagKey, user) {
  const flag = await fetch('https://flags.internal/v1/flags/' + flagKey)
    .then(r => r.json());

  if (flag.type === 'percentage') {
    const bucket = Math.floor(Math.random() * 100);
    return bucket < flag.rollout;
  }
  if (flag.type === 'attribute') {
    return user[flag.attr] === flag.value;
  }
  return flag.defaultOn;
}
